#include "core.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(){try{pg::Config c;auto a=pg::generate(c);check(a.size()==1000,"count");check(a==pg::generate(c),"repeatability");auto b=c;b.seed++;check(a!=pg::generate(b),"seed");std::array<std::size_t,3> n{};int floating=0;for(auto& x:a){++n[x.payment];floating+=x.floating;check(x.amount>=c.min_amount&&x.amount<=c.max_amount,"amount");check(x.term>=c.min_term&&x.term<=c.max_term,"term");check(x.rate>=(x.floating?c.min_spread:c.min_rate)&&x.rate<=(x.floating?c.max_spread:c.max_rate),"rate");}check(n==std::array<std::size_t,3>{600,250,150},"shares");check(floating==300,"floating");check(pg::quotas(7,{5000,5000,0})==std::array<std::size_t,3>{4,3,0},"rounding");b=c;b.count=1;b.floating=10000;b.min_term=b.max_term=1;b.min_amount=b.max_amount=1;auto one=pg::generate(b);check(one[0].floating&&one[0].amount==1&&one[0].term==1,"edges");b.count=0;bool threw=false;try{pg::generate(b);}catch(...){threw=true;}check(threw,"validation");auto dir=std::filesystem::path("test-artifacts");check(!std::filesystem::exists(dir),"test path occupied");std::filesystem::create_directory(dir);pg::save(c,dir/"config.ini");check(a==pg::generate(pg::load(dir/"config.ini")),"roundtrip");pg::report(c,a,dir/"export");check(std::filesystem::file_size(dir/"export/report.html")>1000,"html");{std::ifstream f(dir/"export/portfolio.csv");std::string s;int lines=0;while(std::getline(f,s))++lines;check(lines==1001,"csv");}threw=false;try{pg::report(c,a,dir/"export");}catch(...){threw=true;}check(threw,"overwrite");std::filesystem::remove_all(dir);std::cout<<"All tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
